package stonytark.cinemarr.registry;
import net.minecraft.world.level.block.*;import net.minecraft.world.level.block.state.BlockBehaviour;import net.minecraft.world.level.material.MapColor;import net.minecraftforge.registries.*;import stonytark.cinemarr.Cinemarr;import stonytark.cinemarr.screen.*;
public final class CinemarrBlocks{public static final DeferredRegister<Block> REGISTER=DeferredRegister.create(ForgeRegistries.BLOCKS,Cinemarr.MODID);private static BlockBehaviour.Properties electronic(){return BlockBehaviour.Properties.of().mapColor(MapColor.COLOR_BLACK).strength(2,6).sound(SoundType.METAL);}public static final RegistryObject<ScreenPixelBlock> SCREEN_PIXEL=REGISTER.register("screen_pixel",()->new ScreenPixelBlock(electronic().noOcclusion()));public static final RegistryObject<TvControllerBlock> TV_CONTROLLER=REGISTER.register("tv_controller",()->new TvControllerBlock(electronic()));public static final RegistryObject<Block> TV_CASING=REGISTER.register("tv_casing",()->new Block(electronic()));public static final RegistryObject<Block> TV_SPEAKER=REGISTER.register("tv_speaker",()->new Block(electronic()));public static final RegistryObject<QuickTvBlock> QUICK_TV_144P=quick("quick_tv_144p",stonytark.cinemarr.core.screen.QuickTvPreset.P144),QUICK_TV_240P=quick("quick_tv_240p",stonytark.cinemarr.core.screen.QuickTvPreset.P240),QUICK_TV_480P=quick("quick_tv_480p",stonytark.cinemarr.core.screen.QuickTvPreset.P480),QUICK_TV_720P=quick("quick_tv_720p",stonytark.cinemarr.core.screen.QuickTvPreset.P720),QUICK_TV_1080P=quick("quick_tv_1080p",stonytark.cinemarr.core.screen.QuickTvPreset.P1080),QUICK_TV_1440P=quick("quick_tv_1440p",stonytark.cinemarr.core.screen.QuickTvPreset.P1440),QUICK_TV_4K=quick("quick_tv_4k",stonytark.cinemarr.core.screen.QuickTvPreset.P4K),QUICK_TV_8K=quick("quick_tv_8k",stonytark.cinemarr.core.screen.QuickTvPreset.P8K);private static RegistryObject<QuickTvBlock> quick(String id,stonytark.cinemarr.core.screen.QuickTvPreset preset){return REGISTER.register(id,()->new QuickTvBlock(electronic(),preset));}public static ScreenPixelBlock screenPixel(){return SCREEN_PIXEL.get();}private CinemarrBlocks(){}}
